"""Axis C (exploration, floating point): lower bound for dim S_3, S = subalgebra generated by U_1 + U_2,
for each choice of U_2 passing the weight-two closure.  Generators of weight 3:
   affine part A_3 (x(-1)y(-1)z, x(-2)y, x(-3)1), y(-1) U_2 (y in U_1), L(-1) U_2, u_0 w' (u highest weight
   vector of U_2, w' in U_2).
Vectors are joint weight vectors; the rank is computed weight space by weight space.  Every generated vector lies
in S, hence in U_3: a rank > 956 is a contradiction (to be certified exactly)."""
import sys, json, time, itertools
import numpy as np
import sympy as sp
from gmpy2 import mpq
import lattice_voa as V, cases as C, closure_explore as CE, griess_subalgebras as GS, commutant_griess as CG
if __name__ == '__main__':
    case, ci = sys.argv[1], int(sys.argv[2])
    t0 = time.time()
    T, D, out, types, N1, N2, s13, U1, A2 = CE.setup(case, ci)
    info = json.load(open(f'closure_explore_{case}_{ci}.json'))
    G = json.load(open('griess_subalgebras.json'))[case]['subalgebras'][ci]
    _, basis, _, _ = GS.griess_data(case)
    N3 = CE.Num(3)
    tl = sorted(types)
    # x split into rational parts
    import exact_isotropy_s13 as ES
    xs = [ES.split(c) for c in G['x']]
    x_p = {}; x_q = {}
    for i, (p, q) in enumerate(xs):
        if p: V.vadd(x_p, basis[i + 1], mpq(int(p.p), int(p.q)))
        if q: V.vadd(x_q, basis[i + 1], mpq(int(q.p), int(q.q)))
    x_p, x_q = V.clean(x_p), V.clean(x_q)
    # rational "parts" spanning U2max, each with a weight; U_2 vectors are complex combinations of parts
    def wt(v): return C.weight_of_key(T, next(iter(v)))
    # U_2 basis as list of (list of (coef, rational vector))
    for choice in info['combos'][:1]:
        U2 = []
        for a in A2:
            if a: U2.append([(1.0, a)])
        U2.append([(1.0, basis[0])])
        U2.append([(1.0, x_p), (s13, x_q)] if x_q else [(1.0, x_p)])
        hw = [U2[-2], U2[-1]]            # e, x are invariant (highest weight of type (0,0))
        for tau, l in zip(tl, choice):
            ty = types[tau]; lv = ty['lines'][l]
            for w in range(len(ty['mods'][0][0])):
                comb = []
                for k in range(ty['d']):
                    if ty['mods'][k][0][w]: comb.append((lv[k], ty['mods'][k][0][w]))
                    if ty['mods'][k][1][w]: comb.append((lv[k]*s13, ty['mods'][k][1][w]))
                U2.append(comb)
                if w == 0: hw.append(comb)
        # highest weight vectors of A_2: compute as those A_2 vectors killed by e1_0, e2_0 -> just use all A_2 as 'hw' generators too
        hw_all = hw + [[(1.0, a)] for a in A2 if a]
        gens = {}
        def add(vec):
            if vec is None or not np.any(vec): return
            # split by weight: vectors are weight vectors (sum of terms of one weight) by construction
            nz = np.nonzero(np.abs(vec) > 1e-13)[0]
            if len(nz) == 0: return
            mu = C.weight_of_key(T, N3.keys[nz[0]])
            gens.setdefault(mu, []).append(vec)
        def mode_comb(cu, n, cv, Nout):
            z = np.zeros(len(Nout.keys), dtype=complex)
            for a, va in cu:
                for b, vb in cv:
                    r = V.clean(V.mode_vec(va, n, vb))
                    if r: z += a*b*Nout.vec(r)
            return z
        # A_3 and y(-1) U_2, L(-1) U_2
        for x in U1:
            add(N3.vec(V.clean(V.mode_vec(x, -3, {V.VAC: mpq(1)}))))
            for y in U1:
                add(N3.vec(V.clean(V.mode_vec(x, -2, y))))
        for u in U2:
            add(mode_comb([(1.0, V.OMEGA)], 0, u, N3))          # L(-1) u = omega_0 u
            for y in U1:
                add(mode_comb([(1.0, y)], -1, u, N3))
        print('affine/derivative generators done (%.0fs)' % (time.time() - t0), flush=True)
        for i, u in enumerate(hw_all):
            for v in U2:
                add(mode_comb(u, 0, v, N3))
            if i % 5 == 0: print('  u_0 products: %d/%d hw generators (%.0fs)' % (i + 1, len(hw_all), time.time() - t0), flush=True)
        total = 0; per = {}
        for mu, vs in gens.items():
            M = np.array(vs).T
            r = np.linalg.matrix_rank(M, tol=1e-8*max(1.0, np.abs(M).max()))
            per[str(mu)] = int(r); total += int(r)
        print('choice', choice, ': lower bound for dim S_3 (sum of weight-space ranks) =', total, ' (dim U_3 = 956)')
        json.dump({'choice': choice, 'dimS3_lower': total, 'per_weight': per}, open(f'weight3_explore_{case}_{ci}.json', 'w'), indent=1)
    print('time %.0fs' % (time.time() - t0))
